const sprite_t *sprite_face(sprite_body_t body, sprite_face_t face)
{
    if ((unsigned)body >= SPRITE_BODY_COUNT || (unsigned)face >= SPRITE_FACE_COUNT) {
        return NULL;
    }
    uint8_t i = face_table[body][face];
    return i == 0xff ? NULL : &face_sprites[i];
}

